  const paddedWidth = visibleWidth(padded);
  const inner = "─".repeat(paddedWidth);
  const top = `${chromeBg}${bc}╭${inner}╮${RESET}`;
  const mid = `${chromeBg}${bc}│${BOLD}${padded}${RESET}${chromeBg}${bc}│${RESET}`;
  const bot = `${chromeBg}${bc}╰${inner}╯${RESET}`;
