function renderHeader(run, opts) {
  const { width, theme } = opts;
  const pill = pillFor(run, theme);
  const counts = {
    pending: 0,
    running: 0,
    awaiting_input: 0,
    paused: 0,
    blocked: 0,
    completed: 0,
    failed: 0,
    skipped: 0
  };
  for (const s of run.stages)
    counts[s.status]++;
  const badges = [];
  if (counts.completed > 0)
    badges.push({ text: `✓ ${counts.completed}`, fg: theme.success });
  if (counts.running > 0)
    badges.push({ text: `● ${counts.running}`, fg: theme.warning });
  if (counts.awaiting_input > 0)
    badges.push({ text: `↵ ${counts.awaiting_input}`, fg: theme.info });
  if (counts.paused > 0)
    badges.push({ text: `❚❚ ${counts.paused}`, fg: theme.warning });
  if (counts.pending > 0)
    badges.push({ text: `○ ${counts.pending}`, fg: theme.dim });
  if (counts.skipped > 0)
    badges.push({ text: `⊘ ${counts.skipped}`, fg: theme.dim });
  if (counts.failed > 0)
    badges.push({ text: `✗ ${counts.failed}`, fg: theme.error });
  return renderBandHeader({
    label: pill.label,
    subtitle: run.name,
    badges,
    accent: pill.border,
    width,
    theme
  });
}

