  const top = `${bg}${bc}╭${topMiddle}╮${RESET}`;
  const bottom = `${bg}${bc}╰${"─".repeat(innerWidth)}╯${RESET}`;
  const bodyText = stage.nodeKind === "tool" ? stage.error ?? stage.result ?? "durable tool" : stage.status === "blocked" ? blockedBadgeText(stage, opts.stages, innerWidth) : durationText(stage);
  const bodyHex = durationColor(stage.status, theme);
