// src/tui/stage-chat-view-render-helpers.ts
var ITALIC = "\x1B[3m";
var FG_RESET = "\x1B[39m";
var WEIGHT_RESET = "\x1B[22m";
var ITALIC_RESET = "\x1B[23m";
function blankLine(width) {
  return " ".repeat(width);
}
function cursorBlock2() {
  return "\x1B[7m \x1B[0m";
}
function setComponentFocused(component, focused) {
  const candidate = component;
  if ("focused" in candidate)
    candidate.focused = focused;
}
function setEditorFocused(editor, focused) {
  setComponentFocused(editor, focused);
}
function setEditorPlaceholder(editor, placeholder) {
  const candidate = editor;
  candidate.setPlaceholder?.(placeholder);
}
function setEditorBorderColor(editor, borderColor) {
  const candidate = editor;
  if ("borderColor" in candidate)
    candidate.borderColor = borderColor;
}
function bgFn(hex) {
  const open = hexBg(hex);
  return (text) => open + text + RESET;
}
function editorThemeFromGraphTheme(t) {
  const selected = (text) => hexBg(t.backgroundPanel) + hexToAnsi(t.text) + text + RESET;
  const normal = (text) => hexToAnsi(t.text) + text + RESET;
  return {
    borderColor: (text) => hexToAnsi(t.border) + text + RESET,
    selectList: {
      selectedPrefix: selected,
      selectedText: selected,
      description: (text) => hexToAnsi(t.dim) + text + RESET,
      scrollInfo: (text) => hexToAnsi(t.dim) + text + RESET,
      noMatch: (text) => hexToAnsi(t.warning) + text + RESET,
      normal
    }
  };
}
function takeRows(lines, rows) {
  return lines.slice(0, rows);
}
function widgetHintTargetLineIndex(lines) {
  for (let index = lines.length - 1;index >= 0; index -= 1) {
    if (!isWidgetBottomBorderLine(lines[index] ?? ""))
      return index;
  }
  return Math.max(0, lines.length - 1);
}
function isWidgetBottomBorderLine(line) {
  const plain = stripAnsi(line).trim();
  const chars = Array.from(plain);
  if (chars.length < 2)
    return false;
  const first = chars[0] ?? "";
  const last = chars.at(-1) ?? "";
  if (!"╰└+".includes(first) || !"╯┘+".includes(last))
    return false;
  return chars.slice(1, -1).every((char) => "─═- ".includes(char));
}
function trailingWidgetBorderChar(line) {
  const plain = stripAnsi(line).trimEnd();
  const last = Array.from(plain).at(-1) ?? "";
  return "╯┘┤┴│|+".includes(last) ? last : "";
}
function paint2(text, fg, opts = {}) {
  if (!text)
    return "";
  let out = hexToAnsi(fg);
  if (opts.bold)
    out += BOLD;
  if (opts.italic)
    out += ITALIC;
  if (opts.bg)
    out = hexBg(opts.bg) + out;
  return out + text + RESET;
}
function paintOnFill(text, fg, opts = {}) {
  if (!text)
    return "";
  let out = hexToAnsi(fg);
  if (opts.bold)
    out += BOLD;
  if (opts.italic)
    out += ITALIC;
  let close = FG_RESET;
  if (opts.bold)
    close += WEIGHT_RESET;
  if (opts.italic)
    close += ITALIC_RESET;
  return out + text + close;
}
function stripAnsi(s) {
  return s.replace(/\x1B\[[0-?]*[ -/]*[@-~]/g, "");
}
function blendBg(baseHex, tintHex, alpha) {
  return lerpColor(baseHex, tintHex, Math.max(0, Math.min(1, alpha)));
}
function renderHintsForPrompt(kind, theme) {
  if (kind === "input" || kind === "editor") {
    return `${paint2("enter", theme.textMuted, { bold: true })} Submit · ${paint2("ctrl+c", theme.textMuted, { bold: true })} Skip`;
  }
  if (kind === "custom") {
    return `${paint2("ctrl+x", theme.textMuted, { bold: true })} Return to graph · ${paint2("ctrl+c", theme.textMuted, { bold: true })} Close`;
  }
  return `${paint2("enter", theme.textMuted, { bold: true })} Select · ${paint2("ctrl+c", theme.textMuted, { bold: true })} Skip`;
}

// src/tui/stage-chat-view-types.ts
var VIEW_LINE_COUNT = 32;
var PROMPT_SCROLL_STEP_ROWS = 4;
