// builtin/adversarial-verification-runner.ts
var verifierSchema = Type.Object({
  verdict: Type.Union([Type.Literal("pass"), Type.Literal("fail")]),
  evidence: Type.Array(Type.String()),
  blocking_findings: Type.Array(Type.String())
}, { additionalProperties: false });
var reducerSchema = Type.Object({
  decision: Type.Union([Type.Literal("accept"), Type.Literal("reject"), Type.Literal("repair")]),
  rationale: Type.String(),
  remaining_work: Type.Array(Type.String())
}, { additionalProperties: false });
function structured(value2, guard) {
  return value2 !== undefined && guard(value2) ? value2 : undefined;
}
function isRecord2(value2) {
  return typeof value2 === "object" && value2 !== null && !Array.isArray(value2);
}
function isVerifier(value2) {
  return isRecord2(value2) && (value2.verdict === "pass" || value2.verdict === "fail") && Array.isArray(value2.evidence) && value2.evidence.every((item) => typeof item === "string") && Array.isArray(value2.blocking_findings) && value2.blocking_findings.every((item) => typeof item === "string");
}
function isReducer(value2) {
  return isRecord2(value2) && (value2.decision === "accept" || value2.decision === "reject" || value2.decision === "repair") && typeof value2.rationale === "string" && Array.isArray(value2.remaining_work) && value2.remaining_work.every((item) => typeof item === "string");
}
async function runAdversarialVerification(ctx) {
  const root = await stableArtifactRoot(ctx, "adversarial-verification");
  const rubricPath = join5(root, "rubric.md");
  const candidatePath = join5(root, "candidate.md");
  await writeFile(rubricPath, ["# Verification rubric", "- The candidate satisfies the literal task.", "- Important claims cite observable evidence.", "- Relevant validation is executed and reported with commands run and observed output.", "- File findings cite file:line evidence where applicable.", "- No blocking correctness, safety, or completeness gap remains."].join(`
`));
  await ctx.task("worker", { prompt: renderWorkerPrompt(ctx.inputs.task), context: "fresh", output: candidatePath, outputMode: "file-only" });
  let repairsCompleted = 0;
  let reviewReportPath;
  let verifierArtifactPaths = [];
  let decision = { decision: "reject", rationale: "No valid reducer decision was produced.", remaining_work: ["Reducer did not return a valid structured decision."] };
  for (;; ) {
    verifierArtifactPaths = Array.from({ length: ctx.inputs.verifier_count }, (_, index) => join5(root, `verification-${repairsCompleted}-${index + 1}.json`));
    const reports = await ctx.parallel(verifierArtifactPaths.map((path, index) => ({
      name: `verifier-${repairsCompleted}-${index + 1}`,
      prompt: renderVerifierPrompt(ctx.inputs.task, candidatePath, rubricPath),
      context: "fresh",
      reads: [candidatePath, rubricPath],
      schema: verifierSchema,
      output: path,
      outputMode: "file-only"
    })), { concurrency: Math.min(ctx.inputs.verifier_count, 4), failFast: false });
    const validReports = reports.map((report) => structured(report.structured, isVerifier)).filter((report) => report !== undefined);
    const allVerifiersPassed = validReports.length === ctx.inputs.verifier_count && validReports.every((report) => report.verdict === "pass");
    await writeFile(join5(root, `verification-summary-${repairsCompleted}.json`), JSON.stringify(validReports, null, 2));
    reviewReportPath = join5(root, `review-${repairsCompleted}.json`);
    const reduced = await ctx.task(`reducer-${repairsCompleted}`, {
      prompt: renderReducerPrompt(ctx.inputs.task, candidatePath, verifierArtifactPaths, repairsCompleted, ctx.inputs.max_repairs),
      context: "fresh",
      reads: [candidatePath, rubricPath, ...verifierArtifactPaths],
      schema: reducerSchema,
      output: reviewReportPath,
      outputMode: "file-only"
    });
    decision = structured(reduced.structured, isReducer) ?? decision;
    if (decision.decision === "accept" && !allVerifiersPassed) {
      const remaining = validReports.flatMap((report) => report.blocking_findings);
      decision = repairsCompleted < ctx.inputs.max_repairs ? { decision: "repair", rationale: "Independent verification did not unanimously pass.", remaining_work: remaining } : { decision: "reject", rationale: "Independent verification did not pass before the repair bound was exhausted.", remaining_work: remaining };
    }
    if (decision.decision === "repair" && repairsCompleted >= ctx.inputs.max_repairs) {
      decision = { ...decision, decision: "reject", rationale: `${decision.rationale} Repair bound exhausted.` };
    }
    if (decision.decision !== "repair")
      break;
    repairsCompleted += 1;
    await ctx.task(`repair-${repairsCompleted}`, { prompt: renderRepairPrompt(ctx.inputs.task, candidatePath, reviewReportPath), context: "fresh", reads: [candidatePath, reviewReportPath], output: candidatePath, outputMode: "file-only" });
  }
  const approved = decision.decision === "accept";
  return { result: decision.rationale, approved, repairs_completed: repairsCompleted, candidate_path: candidatePath, review_report_path: reviewReportPath, verifier_artifact_paths: verifierArtifactPaths, artifact_dir: root, remaining_work: approved ? [] : decision.remaining_work };
}

