    remaining_work: Type10.Optional(Type10.String({ description: "Remaining gaps or blockers when incomplete, or none." })),
    review_report: Type10.Optional(Type10.String({ description: "Compact report pointing to the latest reviewer decision artifacts used by the reducer." })),
    review_report_path: Type10.Optional(Type10.String({ description: "JSON artifact path for the latest reviewer decision round." })),
