    preview_path: Type12.Optional(Type12.String({ description: "Absolute path to the generated preview.html file." })),
    preview_file_url: Type12.Optional(Type12.String({ description: "file:// URL for the generated preview.html file." })),
    spec_path: Type12.Optional(Type12.String({ description: "Absolute path to the generated spec.html file." })),
